package com.lifeos.expenses;import com.lifeos.expenses.dto.*;import com.lifeos.shared.exception.*;import com.lifeos.users.*;import org.springframework.stereotype.Service;import java.util.*;@Service public class ExpenseService{private final ExpenseRepository r;private final UserRepository u;public ExpenseService(ExpenseRepository r,UserRepository u){this.r=r;this.u=u;}private User user(String e){return u.findByEmail(e).orElseThrow(()->new ResourceNotFoundException("User not found"));}private Expense owned(Long id,String e){return r.findByIdAndUserId(id,user(e).getId()).orElseThrow(()->new ResourceNotFoundException("Expense not found"));}public List<ExpenseResponse>list(String e){return r.findAllByUserIdOrderByExpenseDateDesc(user(e).getId()).stream().map(ExpenseResponse::from).toList();}public ExpenseResponse get(Long i,String e){return ExpenseResponse.from(owned(i,e));}public ExpenseResponse create(ExpenseRequest q,String e){Expense x=new Expense();x.setUser(user(e));apply(x,q);return ExpenseResponse.from(r.save(x));}public ExpenseResponse update(Long i,ExpenseRequest q,String e){Expense x=owned(i,e);apply(x,q);return ExpenseResponse.from(r.save(x));}public void delete(Long i,String e){r.delete(owned(i,e));}private void apply(Expense x,ExpenseRequest q){x.setDescription(q.description().trim());x.setAmount(q.amount());x.setCategory(q.category());x.setExpenseDate(q.expenseDate());}}
